python3 -c "
import json,math,statistics as st
p=json.load(open('tests/contracts/mdata.Prices/sample.json'))
r={t:[math.log(c[i]/c[i-1]) for i in range(1,len(c))] for t,c in p['closes'].items()}
ret={'base_date':p['dates'][0],'dates':p['dates'][1:],'tickers':p['tickers'],'values':r}
print(json.dumps(ret,indent=2))
v={t:[None if i<2 else st.stdev(x[i-2:i])*math.sqrt(252) for i in range(len(x))] for t,x in r.items()}
print(json.dumps({'returns':ret,'window':2,'annualized':True,'values':v},indent=2))
"
